package com.dorohedoro.hole.client.ui;

import com.dorohedoro.hole.Dorohedoro;
import net.minecraft.client.gui.Font;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.resources.ResourceLocation;

/**
 * Shared Hole UI: riveted sewer-iron windows, recessed grimy panels and smoke-teal trim. The sprites are original art
 * generated by {@code tools/ui/gen-ui.mjs} and nine-sliced, so every panel scales cleanly to any GUI size.
 */
public final class HoleUiTheme {
    private HoleUiTheme() {}

    public static final int TEXT = 0xFFF0E5D2, MUTED = 0xFF9BAEAA, ACCENT = 0xFF69CFC2,
            WARNING = 0xFFF2A77C, BACK = 0xFF151D21, PANEL = 0xFF202A2E, LINE = 0xFF506568,
            BLOOD = 0xFFE2473C, BRASS = 0xFFD8B26A;

    public static final ResourceLocation WINDOW = sprite("menu/window");
    public static final ResourceLocation INSET = sprite("menu/panel");
    public static final ResourceLocation TITLE_PLATE = sprite("menu/title_plate");
    public static final ResourceLocation TAB = sprite("menu/tab");
    public static final ResourceLocation TAB_SELECTED = sprite("menu/tab_selected");
    public static final ResourceLocation BUTTON = sprite("menu/button");
    public static final ResourceLocation BUTTON_HOVER = sprite("menu/button_hover");
    public static final ResourceLocation BUTTON_DISABLED = sprite("menu/button_disabled");
    public static final ResourceLocation DIVIDER = sprite("menu/divider");
    public static final ResourceLocation BAR_FRAME = sprite("hud/bar_frame");

    public static ResourceLocation sprite(String path) {
        return ResourceLocation.fromNamespaceAndPath(Dorohedoro.MOD_ID, path);
    }

    /** Dims the world, then draws the iron window with its title plate across the top. */
    public static void backdrop(GuiGraphics g, int screenW, int screenH, int x, int y, int w, int h) {
        g.fill(0, 0, screenW, screenH, 0xB4080D10);
        g.blitSprite(WINDOW, x - 4, y - 4, w + 8, h + 8);
        g.blitSprite(TITLE_PLATE, x + 6, y + 5, w - 12, 20);
    }

    /** A recessed content well. */
    public static void section(GuiGraphics g, int x, int y, int w, int h) {
        g.blitSprite(INSET, x, y, w, h);
    }

    public static void divider(GuiGraphics g, int x, int y, int w) {
        g.blitSprite(DIVIDER, x, y, w, 4);
    }

    /** A labelled gauge: name on the left, numbers on the right, a framed iron channel underneath. */
    public static void meter(GuiGraphics g, Font font, String name, int value, int max, int x, int y, int w, int color) {
        int safeMax = Math.max(1, max);
        int safe = Math.clamp(value, 0, safeMax);
        g.drawString(font, name, x, y, TEXT, true);
        String numbers = safe + " / " + safeMax;
        g.drawString(font, numbers, x + w - font.width(numbers), y, MUTED, true);
        gauge(g, x, y + 11, w, 9, safe / (float) safeMax, color);
    }

    /** A framed fill: colour body, bright top line and dark base, so a flat colour still reads as a liquid. */
    public static void gauge(GuiGraphics g, int x, int y, int w, int h, float fraction, int color) {
        g.blitSprite(BAR_FRAME, x, y, w, h);
        int inner = w - 4;
        int fill = Math.round(inner * Math.max(0f, Math.min(1f, fraction)));
        if (fill <= 0) return;
        g.fill(x + 2, y + 2, x + 2 + fill, y + h - 2, color);
        g.fill(x + 2, y + 2, x + 2 + fill, y + 3, lighten(color));
        g.fill(x + 2, y + h - 3, x + 2 + fill, y + h - 2, darken(color));
    }

    public static String fit(Font f, String text, int maxWidth) {
        return f.width(text) <= maxWidth ? text : f.plainSubstrByWidth(text, Math.max(0, maxWidth - f.width("..."))) + "...";
    }

    private static int lighten(int c) {
        int r = Math.min(255, ((c >> 16) & 255) + 60), gr = Math.min(255, ((c >> 8) & 255) + 60), b = Math.min(255, (c & 255) + 60);
        return 0xFF000000 | r << 16 | gr << 8 | b;
    }

    private static int darken(int c) {
        int r = ((c >> 16) & 255) * 3 / 5, gr = ((c >> 8) & 255) * 3 / 5, b = (c & 255) * 3 / 5;
        return 0xFF000000 | r << 16 | gr << 8 | b;
    }
}
